// @thaireport/client — หน้าต่างเดียวระหว่าง designer (browser) กับ engine ตัวเดียวกับ CLI
//
// WASM ถูกโหลดจาก public/tr-wasm/ ด้วย URL ตรงๆ (ไม่ผ่าน bundler) เหตุผลเดียวกับ
// pdf.js ใน designer: wasm ต้องมาทั้งก้อนและโหลดครั้งเดียว ไม่ควรอยู่ใน main bundle
// ไฟล์ถูกคัดลอกโดย scripts/copy-wasm.mjs ตอน prebuild/predev
//
// สำคัญ: ต้องเก็บ "namespace ของโมดูล" ไว้เรียก ไม่ใช่ InitOutput
// InitOutput คือ export ดิบของ wasm — ฟังก์ชันที่คืน String จะได้ [ptr, len] กลับมา
// ต้องผ่าน wrapper ของ wasm-bindgen ถึงจะได้ string จริง

// ค่า default คำนวณตอนเรียก ไม่ใช่ตอน import — โมดูลนี้ต้อง import ได้ใน Node (test) ด้วย
const defaultUrl = (file) =>
  typeof document !== "undefined" ? new URL(file, document.baseURI).href : undefined;

let mod = null;
let initPromise = null;

/**
 * โหลด WASM + ฟอนต์ที่ฝังอยู่ในตัวมันเอง (Sarabun/Noto Sans Thai)
 * เรียกซ้ำได้ — ครั้งที่สองขึ้นไปได้ promise เดิม
 *
 * @param {{moduleUrl?: string|URL, binary?: string|URL|ArrayBufferView}} [opts]
 *   ปล่อยไว้เพื่อใช้ไฟล์ใน public/tr-wasm/ — host ที่เก็บ wasm ไว้ที่อื่น (CDN)
 *   สามารถส่งมาแทนได้ ค่า `binary` รับ bytes เป็น ArrayBuffer ได้ (ข้าม fetch)
 * @returns {Promise<void>}
 */
export function initThaireport(opts) {
  initPromise ??= (async () => {
    const m = await import(
      /* @vite-ignore */ String(opts?.moduleUrl ?? defaultUrl("tr-wasm/tr_wasm.js"))
    );
    await m.default({ module_or_path: opts?.binary ?? defaultUrl("tr-wasm/tr_wasm_bg.wasm") });
    mod = m;
  })().catch((e) => {
    // ล้าง cache เพื่อให้กดลองใหม่ได้ ไม่ต้องรีโหลดหน้าเว็บ
    initPromise = null;
    throw e;
  });
  return initPromise;
}

/**
 * เรนเดอร์ Template + data เป็น PDF จริงใน browser ด้วย engine ตัวเดียวกับ CLI
 *
 * @param {object} template โครงสร้างเอกสาร (หน่วย mm)
 * @param {object} data     ข้อมูลสำหรับ bind
 * @returns {Promise<{ok: true, pdf_base64: string, bytes: number, page_count: number}
 *                  | {ok: false, error: string}>}
 */
export async function previewTemplate(template, data) {
  await initThaireport();
  let res;
  try {
    res = JSON.parse(mod.preview_template(JSON.stringify(template ?? {}), JSON.stringify(data ?? {})));
  } catch (e) {
    return { ok: false, error: `เรนเดอร์ไม่สำเร็จ: ${e?.message ?? e}` };
  }
  if (!res?.ok) return { ok: false, error: res?.error ?? "เรนเดอร์ไม่สำเร็จ" };
  return res;
}

/** โหลด WASM เสร็จแล้วหรือยัง (ใช้เช็คเร็ว ๆ โดยไม่ต้อง await) */
export function isReady() {
  return mod !== null;
}
